{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "화재·수해 시 반려동물과 함께 대피하는 방법을 배울 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제24조제2항제11호에 따르면 동물복지지원센터는 재난 발생 시 소유자등이 반려동물과 안전하게 대피하기 위하여 필요한 대피 방법에 관한 교육을 수행할 수 있다. 따라서 화재나 수해 등 재난 상황에서 반려동물과 함께 대피하는 방법을 배우는 교육은 동물복지지원센터의 수행 기능에 포함된다. 다만 실제 교육 운영 여부나 신청 방법 등 세부 사항은 원문에 규정되어 있지 않다.",
          "b_ids": "동물보호:제24조제2항제11호, 동물보호:제24조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "반려동물 대피교육이 서울시 동물복지지원센터의 업무에 해당하는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제24조제2항은 동물복지지원센터에서 수행할 수 있는 기능을 각 호로 정하고 있고, 같은 항 제11호에서 재난 발생 시 소유자등이 반려동물과 안전하게 대피하기 위하여 필요한 대피 방법에 관한 교육을 명시하고 있다. 따라서 반려동물 대피교육은 서울시 동물복지지원센터의 수행 가능 업무에 해당한다.",
          "b_ids": "동물보호:제24조제2항, 동물보호:제24조제2항제11호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
